const V = {{v}};
const bits = V.toString(2).padStart(8, '0');
ctx.font = '28px ui-monospace, monospace';
bits.split('').forEach((b, i) => {
  ctx.fillStyle = b === '1' ? '#60a5fa' : '#374151';
  ctx.fillRect(16 + i * 38, 30, 32, 40);
  ctx.fillStyle = b === '1' ? '#0b1220' : '#9ca3af';
  ctx.fillText(b, 26 + i * 38, 60);
});
ctx.font = '12px ui-monospace, monospace'; ctx.fillStyle = '#9ca3af';
bits.split('').forEach((_, i) => ctx.fillText(String(2 ** (7 - i)), 18 + i * 38, 88));
ctx.font = '15px system-ui'; ctx.fillStyle = '#eee';
ctx.fillText('10진 ' + V + '  ·  16진 0x' + V.toString(16).toUpperCase().padStart(2, '0'), 16, 128);
